fn named_param_comma_resets_annotation(&self) -> bool {
    self.named_param_scan.parens == 1
}

fn note_named_param_comma(&mut self) {
    if self.named_param_scan.parens == 1 {
        self.named_param_scan.annotated_func_arg = false;
    }
}

fn named_param_equal_is_active(&self) -> bool {
    self.in_type_params()
        || (self.named_param_scan.parens > 0 && self.named_param_scan.fstrings == 0)
}

fn named_param_equal_needs_spaces(&self) -> bool {
    self.in_type_params()
        || (self.named_param_scan.annotated_func_arg && self.named_param_scan.parens == 1)
}

fn named_param_missing_space_before(&self, token: &LogicalLineToken) -> bool {
    token.start() == self.named_param_scan.prev_end
        && self.named_param_scan.prev_end != TextSize::new(0)
}

fn remember_named_param_end(&mut self, token: &LogicalLineToken) {
    self.named_param_scan.prev_end = token.end();
}

pub(crate) fn check_missing_operator_space(
    &mut self,
    line: &LogicalLine,
    context: &mut LogicalLinesContext,
) {
    self.operator_scan = OperatorScan::default();
    let mut tokens = line.tokens().iter().peekable();
    let first_token = tokens
        .by_ref()
        .find(|token| !is_non_logical_token(token.kind()));
    let Some(mut prev_token) = first_token else {
        return;
    };
    self.prime_operator_scan(prev_token);
    while let Some(token) = tokens.next() {
        let kind = token.kind();
        self.visit_token_kind(kind);
        if is_non_logical_token(kind) {
            continue;
        }
        self.note_operator_token(kind);
        let needs_space = if self.operator_equal_is_keyword_arg(kind) {
            NeedsSpace::No
        } else if kind == TokenKind::Slash {
            slash_operator_space(tokens.peek().map(|token| token.kind()))
        } else if kind.is_unary_arithmetic_operator()
            || matches!(kind, TokenKind::Star | TokenKind::DoubleStar)
        {
            unary_or_star_operator_space(kind, prev_token.kind())
        } else if closer_follows_operator(tokens.peek().map(|token| token.kind())) {
            NeedsSpace::No
        } else if operator_whitespace_needed(kind) {
            NeedsSpace::Yes
        } else {
            NeedsSpace::No
        };
        if needs_space != NeedsSpace::No {
            let has_leading_trivia =
                prev_token.end() < token.start() || is_non_logical_token(prev_token.kind());
